___CSS_LOADER_EXPORT___.push([module.id, ".overlay_venta{align-items:center;background-color:rgba(0,0,0,.7);color:#fff;display:flex;font-size:24px;height:100%;justify-content:center;left:0;position:fixed;top:0;visibility:hidden;width:100%;z-index:99999999999!important}.loader_cotizacion_create{animation:pillerPushUp 4s linear infinite;background-image:linear-gradient(#ddd 50px,transparent 0),linear-gradient(#ddd 50px,transparent 0),linear-gradient(#ddd 50px,transparent 0),linear-gradient(#ddd 50px,transparent 0),linear-gradient(#ddd 50px,transparent 0);background-position:0 90px,15px 78px,30px 66px,45px 58px,60px 50px;background-repeat:no-repeat;background-size:8px 100%;height:100px;position:relative;width:75px}.loader_cotizacion_create:after{animation:ballStepUp 4s linear infinite;background:#de3500;border-radius:50%;bottom:10px;content:\"\";height:10px;left:0;position:absolute;width:10px}@keyframes pillerPushUp{0%,40%,to{background-position:0 90px,15px 78px,30px 66px,45px 58px,60px 50px}50%,90%{background-position:0 50px,15px 58px,30px 66px,45px 78px,60px 90px}}@keyframes ballStepUp{0%{transform:translate(0)}5%{transform:translate(8px,-14px)}10%{transform:translate(15px,-10px)}17%{transform:translate(23px,-24px)}20%{transform:translate(30px,-20px)}27%{transform:translate(38px,-34px)}30%{transform:translate(45px,-30px)}37%{transform:translate(53px,-44px)}40%{transform:translate(60px,-40px)}50%{transform:translate(60px)}57%{transform:translate(53px,-14px)}60%{transform:translate(45px,-10px)}67%{transform:translate(37px,-24px)}70%{transform:translate(30px,-20px)}77%{transform:translate(22px,-34px)}80%{transform:translate(15px,-30px)}87%{transform:translate(7px,-44px)}90%{transform:translateY(-40px)}to{transform:translate(0)}}", "",{"version":3,"sources":["webpack://./resources/js/views/Ventas/documentos/appVenta.vue"],"names":[],"mappings":"AACA,eAaA,kBAAA,CANA,+BAAA,CAOA,UAAA,CAHA,YAAA,CAIA,cAAA,CATA,WAAA,CAMA,sBAAA,CARA,MAAA,CAHA,cAAA,CAEA,KAAA,CAaA,iBAAA,CAXA,UAAA,CAIA,6BAQA,CAGA,0BAYA,yCAAA,CAPA,6NAIA,CAEA,kEAAA,CAPA,2BAAA,CAMA,wBAAA,CAPA,YAAA,CAFA,iBAAA,CACA,UAWA,CAEA,gCASA,uCAAA,CAFA,kBAAA,CACA,iBAAA,CALA,WAAA,CAFA,UAAA,CAKA,WAAA,CAFA,MAAA,CAFA,iBAAA,CAGA,UAKA,CAEA,wBAEA,UAGA,kEACA,CAEA,QAEA,kEACA,CACA,CAEA,sBACA,GACA,sBACA,CAEA,GACA,8BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,yBACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,+BACA,CAEA,IACA,8BACA,CAEA,IACA,2BACA,CAEA,GACA,sBACA,CACA","sourcesContent":["<style>\n.overlay_venta {\n    position: fixed;\n    /* Fija el overlay para que cubra todo el viewport */\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background-color: rgba(0, 0, 0, 0.7);\n    /* Color oscuro con opacidad */\n    z-index: 99999999999 !important;\n    /* Asegura que el overlay esté sobre todo */\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    color: white;\n    font-size: 24px;\n    visibility: hidden;\n}\n\n/*========== LOADER SPINNER =======*/\n.loader_cotizacion_create {\n    position: relative;\n    width: 75px;\n    height: 100px;\n    background-repeat: no-repeat;\n    background-image: linear-gradient(#DDD 50px, transparent 0),\n        linear-gradient(#DDD 50px, transparent 0),\n        linear-gradient(#DDD 50px, transparent 0),\n        linear-gradient(#DDD 50px, transparent 0),\n        linear-gradient(#DDD 50px, transparent 0);\n    background-size: 8px 100%;\n    background-position: 0px 90px, 15px 78px, 30px 66px, 45px 58px, 60px 50px;\n    animation: pillerPushUp 4s linear infinite;\n}\n\n.loader_cotizacion_create:after {\n    content: '';\n    position: absolute;\n    bottom: 10px;\n    left: 0;\n    width: 10px;\n    height: 10px;\n    background: #de3500;\n    border-radius: 50%;\n    animation: ballStepUp 4s linear infinite;\n}\n\n@keyframes pillerPushUp {\n\n    0%,\n    40%,\n    100% {\n        background-position: 0px 90px, 15px 78px, 30px 66px, 45px 58px, 60px 50px\n    }\n\n    50%,\n    90% {\n        background-position: 0px 50px, 15px 58px, 30px 66px, 45px 78px, 60px 90px\n    }\n}\n\n@keyframes ballStepUp {\n    0% {\n        transform: translate(0, 0)\n    }\n\n    5% {\n        transform: translate(8px, -14px)\n    }\n\n    10% {\n        transform: translate(15px, -10px)\n    }\n\n    17% {\n        transform: translate(23px, -24px)\n    }\n\n    20% {\n        transform: translate(30px, -20px)\n    }\n\n    27% {\n        transform: translate(38px, -34px)\n    }\n\n    30% {\n        transform: translate(45px, -30px)\n    }\n\n    37% {\n        transform: translate(53px, -44px)\n    }\n\n    40% {\n        transform: translate(60px, -40px)\n    }\n\n    50% {\n        transform: translate(60px, 0)\n    }\n\n    57% {\n        transform: translate(53px, -14px)\n    }\n\n    60% {\n        transform: translate(45px, -10px)\n    }\n\n    67% {\n        transform: translate(37px, -24px)\n    }\n\n    70% {\n        transform: translate(30px, -20px)\n    }\n\n    77% {\n        transform: translate(22px, -34px)\n    }\n\n    80% {\n        transform: translate(15px, -30px)\n    }\n\n    87% {\n        transform: translate(7px, -44px)\n    }\n\n    90% {\n        transform: translate(0, -40px)\n    }\n\n    100% {\n        transform: translate(0, 0);\n    }\n}\n</style>\n\n<template>\n    <div>\n        <div class=\"overlay_venta\">\n            <span class=\"loader_cotizacion_create\"></span>\n        </div>\n        <div class=\"row wrapper border-bottom white-bg page-heading align-items-end\">\n            <div class=\"col-12 col-md-10\">\n                <h2 style=\"text-transform:uppercase\">\n                    <b v-if=\"ruta == 'index'\">Lista de Documentos de Venta</b>\n                    <b v-if=\"ruta == 'create'\">REGISTRAR NUEVO DOCUMENTO DE VENTA</b>\n                </h2>\n                <ol class=\"breadcrumb\">\n                    <li class=\"breadcrumb-item\">\n                        <a :href=\"routes('HOME')\">Panel de Controls</a>\n                    </li>\n                    <li class=\"breadcrumb-item\" :class=\"ruta == 'index' ? 'active' : ''\">\n                        <template v-if=\"ruta == 'index'\">\n                            <strong>Documentos de Ventas</strong>\n                        </template>\n                        <template v-else>\n                            <a href=\"javascript:void(0)\" @click.prevent=\"ruta = 'index'\">\n                                Documentos de Ventas\n                            </a>\n                        </template>\n                    </li>\n                    <li class=\"breadcrumb-item\" v-if=\"ruta == 'create' ? 'active' : ''\"\n                        :class=\"ruta == 'create' ? 'active' : ''\">\n                        <strong>Registrar</strong>\n                    </li>\n                </ol>\n            </div>\n            <div class=\"col-lg-2 col-md-2\" v-if=\"ruta == 'index'\">\n                <button type=\"button\" class=\"btn btn-block btn-w-m btn-success m-t-md\" @click.prevent=\"irVentaNueva\">\n                    <i class=\"fa fa-plus-square\"></i> NUEVO\n                </button>\n            </div>\n        </div>\n        <template v-if=\"ruta == 'index'\">\n            <venta-lista :imginicial=\"imginicial\" :lst_modos_pago=\"this.lst_modos_pago\" />\n        </template>\n        <template v-if=\"ruta == 'create'\">\n            <venta-create :ruta.sync=\"ruta\" :v_sede=\"this.v_sede\" :registrador=\"this.registrador\"\n                :idcotizacion=\"idcotizacion\"\n                :lst_almacenes=\"this.lst_almacenes\"\n                :lst_departamentos_base=\"this.lst_departamentos_base\"\n                :lst_provincias_base=\"this.lst_provincias_base\"\n                :lst_distritos_base=\"this.lst_distritos_base\"\n                :lst_metodos_pago = \"this.lst_modos_pago\"\n                :lst_origenes_ventas=\"this.lst_origenes_ventas\" />\n        </template>\n    </div>\n</template>\n\n<script>\n\nexport default {\n    name: \"AppVue\",\n    props: [\n        \"imginicial\",\n        \"v_sede\",\n        \"registrador\",\n        \"lst_almacenes\",\n        \"ls_origenes_ventas\",\n        \"lst_departamentos_base\",\n        \"lst_provincias_base\",\n        \"lst_distritos_base\",\n        \"lst_modos_pago\",\n        \"lst_origenes_ventas\"\n    ],\n    components: {\n    },\n    data() {\n        return {\n            ruta: \"index\",\n            idcotizacion: 0\n        }\n    },\n    watch: {\n        ruta(data) {\n\n            if (data == \"create\") {\n                let cotizacion = this.idcotizacion == 0 ? '' : '?cotizacion=' + this.idcotizacion;\n                let url = route('ventas.documento.create') + cotizacion;\n                history.pushState(null, \"\", url);\n            }\n\n            if (data == \"index\") {\n                history.pushState(null, \"\", route('ventas.documento.index'));\n                this.idcotizacion = 0;\n            }\n        }\n    },\n    created() {\n        try {\n\n            let url = location.href.split('/');\n            let pathUrl = url[url.length - 1];\n            let pathUrlGet = pathUrl.split('?');\n            if (pathUrlGet.length == 1) {\n                if (pathUrlGet.shift() == 'create') {\n                    this.ruta = \"create\";\n                }\n\n            } else {\n                let parametros = pathUrlGet[1];\n                parametros = parametros.split(\"=\");\n                if (parametros[0] === \"cotizacion\") {\n                    this.idcotizacion = Number(parametros[1]);\n                    this.ruta = \"create\";\n                } else {\n                    throw \"la variable \" + parametros + \" no es valido.\";\n                }\n            }\n        } catch (ex) {\n            console.log(ex);\n        }\n\n    },\n    methods: {\n        async irVentaNueva() {\n            try {\n                this.mostrarAnimacionVenta();\n                const res = await this.axios.get(route('utilidades.getCajaMovimiento'));\n                if (res.data.success) {\n                    toastr.success(res.data.message,'OPERACIÓN COMPLETADA');\n                    this.ruta   =   'create';\n                } else {\n                    toastr.error(res.data.message,'ERROR EN EL SERVIDOR');\n                }\n            } catch (error) {\n                toastr.error(error, 'ERROR EN LA PETICIÓN VALIDAR CAJA');\n            }finally{\n                this.ocultarAnimacionVenta();\n            }\n        },\n        routes(tipo) {\n            switch (tipo) {\n                case \"HOME\": {\n                    return route('home');\n                    break;\n                }\n                case \"CREATE\": {\n                    return route('ventas.documento.create');\n                    break;\n                }\n            }\n        },\n        mostrarAnimacionVenta() {\n            document.querySelector('.overlay_venta').style.visibility = 'visible';\n        },\n        ocultarAnimacionVenta() {\n            document.querySelector('.overlay_venta').style.visibility = 'hidden';\n        }\n    },\n    mounted() {\n\n    }\n\n}\n\n\n</script>\n"],"sourceRoot":""}]);
